-- 이전 마네킹 등록 SQL에 지정된 계정으로 등록합니다.
-- 다른 계정에 넣으려면 target_user_id를 해당 User UID로 바꾸세요.
-- japanese.sql 적용 후 Supabase SQL Editor에서 전체를 실행하세요.
-- 같은 계정에 같은 문장이 있으면 건너뜁니다.
begin;
do $import$
declare
  target_user_id uuid := '8716647f-9104-4d21-b9f4-6a33b1ea4685';
begin
  if not exists (select 1 from auth.users where id = target_user_id) then
    raise exception '등록할 사용자를 찾을 수 없습니다. User UID를 확인하세요.';
  end if;
  insert into public.little_plan_japanese (user_id, expression, reading, meaning)
  select target_user_id, phrase.expression, phrase.reading, phrase.meaning
  from (values
    (1, 'Sが昔山に行ったときついて来た幽霊「カケル」くんが居る。', 'エスがむかしやまにいったときついてきたゆうれい「カケル」くんがいる。', 'S가 예전에 산에 갔을 때 따라온 ''카케루''라는 유령이 있다.'),
    (2, '長くなるから詳しいとこは省くね。', 'ながくなるからくわしいとこははぶくね。', '이야기가 길어지니까 자세한 부분은 생략할게. 「詳しいとこ」는 「詳しいところ」의 구어체. 「省く」는 생략하다.'),
    (3, 'んで、S家までついて来て普通にみんなカケル君を認めて暮らしてるそうだ。', 'んで、エスけまでついてきてふつうにみんなカケルくんをみとめてくらしてるそうだ。', '그래서 S의 집까지 따라왔고, 가족 모두가 카케루를 자연스럽게 받아들이며 함께 살고 있다고 한다. 「んで」는 「それで」의 구어체. 「〜そうだ」는 전해 들은 이야기.'),
    (4, 'あるときS弟が泣きながら家に帰って来た、「どうしたの！」Sが尋ねるが、犬に追いかけられただけだと言う。', 'あるときエスのおとうとがなきながらいえにかえってきた、「どうしたの！」エスがたずねるが、いぬにおいかけられただけだという。', '어느 날 S의 남동생이 울면서 집에 돌아왔다. S가 ''무슨 일이야!''라고 물었지만, 개에게 쫓겼을 뿐이라고 말했다. 「泣きながら」는 울면서, 「追いかけられる」는 쫓기다.'),
    (5, 'でもカバンの中に入っていた筆箱がボロボロだからおかしい事に気付いた。', 'でもカバンのなかにはいっていたふでばこがボロボロだからおかしいことにきづいた。', '하지만 가방 안에 있던 필통이 너덜너덜해진 것을 보고 뭔가 이상하다는 사실을 알아차렸다. 「ボロボロ」는 낡거나 망가져 엉망인 상태. 「気付く」는 알아차리다.'),
    (6, '次の日、カケル君に「今日、S弟についていってみてくれない？」と頼んで見る。', 'つぎのひ、カケルくんに「きょう、エスのおとうとについていってみてくれない？」とたのんでみる。', '다음 날 카케루에게 ''오늘 S의 동생을 한번 따라가 봐 줄래?''라고 부탁해 본다. 「〜てくれない？」는 친근한 부탁 표현. 「〜てみる」는 시험 삼아 해 보다.'),
    (7, 'これそう言えば1000行ったらどうすればいいのでしょうか...', 'これそういえばせんいったらどうすればいいのでしょうか...', '그러고 보니 이거 1000까지 가면 어떻게 해야 하는 걸까요? 게시판의 댓글 번호가 1000에 도달하는 상황을 말하는 것으로 보인다. 「そう言えば」는 그러고 보니, 「どうすればいい」는 어떻게 하면 좋을까.'),
    (8, '昼休みのカケル君の報告に依ると、S弟はどうやらいじめられているらしい。', 'ひるやすみのカケルくんのほうこくによると、エスのおとうとはどうやらいじめられているらしい。', '점심시간에 카케루가 보고한 바에 따르면, S의 남동생은 아무래도 괴롭힘을 당하고 있는 모양이었다. 「〜によると」는 ~에 따르면. 「どうやら〜らしい」는 아무래도 ~인 모양이다.'),
    (9, 'Sは弟と同じ学校だったから、クラスを覗きに行ったんだって。', 'エスはおとうととおなじがっこうだったから、クラスをのぞきにいったんだって。', 'S는 동생과 같은 학교에 다녔기 때문에 동생 반을 들여다보러 갔다고 한다. 「覗く」는 들여다보다, 엿보다. 「〜んだって」는 ~라고 하더라.'),
    (10, '教室からすごい音が聞こえて来た、弟の机は投げ捨てられ。鞄で殴られて居る。', 'きょうしつからすごいおとがきこえてきた、おとうとのつくえはなげすてられ。かばんでなぐられている。', '교실에서 엄청난 소리가 들려왔다. 동생의 책상은 내던져졌고, 동생은 가방으로 얻어맞고 있었다. 「投げ捨てる」는 내던지다. 「殴られる」는 얻어맞다. 원문의 「投げ捨てられ」는 문장이 중간에 끊긴 형태.'),
    (11, 'もうクラス全体がそう言う雰囲気に慣れてるみたいだった。', 'もうクラスぜんたいがそういうふんいきになれてるみたいだった。', '이미 반 전체가 그런 분위기에 익숙해져 있는 것 같았다. 「〜に慣れる」는 ~에 익숙해지다. 「〜みたいだ」는 ~인 것 같다.'),
    (12, '言葉も出ずにSは震えた、何も出来ずにいったん家に帰って母に報告。', 'ことばもでずにエスはふるえた、なにもできずにいったんいえにかえってははにほうこく。', 'S는 말도 나오지 않아 몸을 떨었고, 아무것도 하지 못한 채 일단 집으로 돌아가 어머니에게 알렸다. 「〜ずに」는 ~하지 않고. 「いったん」은 일단, 우선. 「震える」는 떨다.'),
    (13, '黙認してた教師は左遷され、主犯格の少年の家に怒鳴り込んだらしい。', 'もくにんしてたきょうしはさせんされ、しゅはんかくのしょうねんのいえにどなりこんだらしい。', '괴롭힘을 묵인하던 교사는 좌천되었고, 주동자 소년의 집에는 찾아가 호통을 쳤다고 한다. 「黙認する」는 묵인하다. 「左遷される」는 좌천되다. 「怒鳴り込む」는 찾아가서 거세게 항의하다.'),
    (14, 'でもやっぱり子供だから、少年はいじめをやめない。', 'でもやっぱりこどもだから、しょうねんはいじめをやめない。', '하지만 역시 어린아이여서인지 그 소년은 괴롭힘을 그만두지 않았다. 「やっぱり」는 역시, 아무래도. 「いじめをやめる」는 괴롭힘을 그만두다.'),
    (15, 'カケル君はSにかなりなついてるみたいで、Sが嫌な気分になるような事を誰かがすると、本当にその場の雰囲気が凍りつくというか、カケル君が怒るんだ。', 'カケルくんはエスにかなりなついてるみたいで、エスがいやなきぶんになるようなことをだれかがすると、ほんとうにそのばのふんいきがこおりつくというか、カケルくんがおこるんだ。', '카케루는 S를 상당히 따르는 것 같아서, 누군가 S의 기분을 상하게 하면 그 자리의 분위기가 정말 얼어붙는다고 할까, 카케루가 화를 낸다. 「懐く」는 사람을 잘 따르다. 「凍りつく」는 얼어붙다. 「〜というか」는 ~라고 할까.'),
    (16, 'で、暫くS弟についてたから弟にも懐いて。虐めてた少年が遊具から落ちて大怪我をしたり、雰囲気に耐えられなくなる子どもが出てきた。', 'で、しばらくエスのおとうとについてたからおとうとにもなついて。いじめてたしょうねんがゆうぐからおちておおけがをしたり、ふんいきにたえられなくなるこどもがでてきた。', '그리고 한동안 S의 동생을 따라다니면서 동생에게도 정이 들었다. 괴롭히던 소년이 놀이기구에서 떨어져 크게 다치거나, 그 분위기를 견디지 못하는 아이들이 나타났다. 「大怪我」는 큰 부상. 「耐えられない」는 견딜 수 없다. 「〜たり」는 여러 사례를 열거할 때 사용.'),
    (17, '根本的な解決にはなってなくて、弟は転校してしまう。', 'こんぽんてきなかいけつにはなってなくて、おとうとはてんこうしてしまう。', '근본적인 해결은 되지 못했고, 결국 동생은 전학을 가고 만다. 「根本的」는 근본적인. 「〜てしまう」는 일이 끝나 버렸거나 유감스러운 결과가 발생했음을 나타낸다.'),
    (18, 'Sの方からカケル君になんとか理解してもらい今はそんな事ない見たいだけど、機嫌が悪くなってものを壊す事はあるらしい。', 'エスのほうからカケルくんになんとかりかいしてもらいいまはそんなことないみたいだけど、きげんがわるくなってものをこわすことはあるらしい。', 'S가 어떻게든 카케루를 이해시켜서 지금은 그런 일은 없는 것 같지만, 기분이 나빠지면 물건을 부수는 일은 있다고 한다. 「なんとか」는 어떻게든. 「〜てもらう」는 상대에게 어떤 행동을 해 달라고 하여 그 도움을 받다. 「機嫌が悪い」는 기분이 나쁘다.')
  ) as phrase(position, expression, reading, meaning)
  where not exists (
    select 1 from public.little_plan_japanese existing
    where existing.user_id = target_user_id and existing.expression = phrase.expression
  )
  order by phrase.position;
end
$import$;
commit;
